props.css:
.feature-card {
  background: white;
  border-radius: 8px;
  padding: 30px;
  margin-bottom: 30px;
  box-shadow: 0 2px 15px rgba(0,0,0,0.1);
  transition: transform 0.3s ease;
}
.feature-card:hover {
  transform: translateY(-5px);
}
.feature-card h3, .feature-card h4 {
  color: #47424C;
  margin-bottom: 15px;
}
.feature-icon {
  font-size: 48px;
  margin-bottom: 20px;
  display: block;
}
.feature-list {
  list-style: none;
  padding: 0;
}
.feature-list li {
  padding: 10px 0;
  border-bottom: 1px solid #e0e0e0;
}
.feature-list li:before {
  content: "✓";
  color: #8490ff;
  font-weight: bold;
  margin-right: 10px;
  font-size: 18px;
}
.highlight-box {
  background: linear-gradient(135deg, #8490ff 0%, #62bdfc 100%);
  color: white;
  padding: 40px;
  border-radius: 8px;
  margin: 30px 0;
}
.highlight-box h3 {
  color: white;
  margin-bottom: 20px;
  font-weight: 700;
}
.highlight-box p {
  color: white;
  text-shadow: 0 1px 2px rgba(0,0,0,0.1);
}
.highlight-box .lead {
  color: white;
  font-weight: 500;
}
.stat-box {
  text-align: center;
  padding: 20px;
}
.stat-box .number {
  font-size: 48px;
  font-weight: bold;
  color: #8490ff;
  display: block;
}
.stat-box .label {
  font-size: 16px;
  color: #666;
  margin-top: 10px;
}
.comparison-badge {
  background: #8490ff;
  color: white;
  padding: 8px 20px;
  border-radius: 20px;
  font-weight: 600;
  display: inline-block;
  margin: 10px 5px;
}
